# list ordered by "suffix", i. e. actual field name
mdfieldlist3 = []
tmplist = mdfieldlist2
uniqsuffixlist = []
for s in mdfieldlist2:
    suff = s[11:]
    if suff not in uniqsuffixlist:
        uniqsuffixlist.append(suff)
for s in uniqsuffixlist:
    for m in mdfieldlist2:
        suff = m[11:]
        if s == suff:
            mdfieldlist3.append(m)



